async () => {
  const set = async (k, v) => { const e = document.querySelector(`[data-test=${k}]`); e.focus(); e.value = v; e.dispatchEvent(new Event('input', {bubbles:true})); e.dispatchEvent(new Event('blur', {bubbles:true})); await new Promise(r=>setTimeout(r,150)); };
  const p3 = () => document.querySelector('[data-test=proceed-3]').disabled;
  const orig = { address: 'Main Street 1', city: 'Amsterdam', state: 'Noord-Holland', country: 'Netherlands', postcode: '1011AA' };
  const res = {};
  for (const k of Object.keys(orig)) await set(k, orig[k]);
  res.allValid = p3();
  for (const k of Object.keys(orig)) { await set(k, ''); res['empty_'+k] = { proceedDisabled: p3(), invalidClass: document.querySelector(`[data-test=${k}]`).className.includes('ng-invalid') }; await set(k, orig[k]); }
  const lim = { address: 70, city: 40, state: 40, country: 40, postcode: 10 };
  for (const [k, n] of Object.entries(lim)) { await set(k, 'A'.repeat(n + 1)); res['over_'+k] = { len: document.querySelector(`[data-test=${k}]`).value.length, proceedDisabled: p3() }; await set(k, orig[k]); }
  await set('city', 'Ams'); res.city3chars = { proceedDisabled: p3() }; await set('city', 'Amsterdam');
  return res;
}

