input.function:
async () => {
  const q = document.querySelector('[data-test=quantity]'); const add = document.querySelector('[data-test=add-to-cart]');
  const out = [];
  for (const v of ['0', '-1', '1', '999999999', '1000000000', 'abc']) {
    sessionStorage.removeItem('cart');
    q.focus(); q.value = v; q.dispatchEvent(new Event('input', {bubbles:true})); q.dispatchEvent(new Event('change', {bubbles:true})); q.blur();
    await new Promise(r=>setTimeout(r,200));
    const shown = q.value; const addDisabled = add.disabled;
    add.click(); await new Promise(r=>setTimeout(r,700));
    const cart = JSON.parse(sessionStorage.getItem('cart') || 'null');
    out.push({ typed: v, fieldAfter: shown, addDisabled, cartQty: cart?.[0]?.quantity ?? null, cartTotal: cart?.[0]?.total ?? null });
  }
  sessionStorage.removeItem('cart');
  return out;
}

