async () => {
  const collect = () => [...document.querySelectorAll('a[href^="#/product/"], a.card')].map(a => ({ id: (a.getAttribute('href')||'').split('/').pop(), name: a.querySelector('[data-test=product-name]')?.textContent.trim(), img: a.querySelector('img')?.getAttribute('src'), imgOk: (() => { const i = a.querySelector('img'); return i ? (i.complete && i.naturalWidth > 0) : null })() }));
  const pages = [];
  for (const p of [1,2,3]) {
    if (p > 1) { const link = [...document.querySelectorAll('.pagination a, .pagination li')].find(e => e.textContent.trim().replace(/\D/g,'') === String(p)); link?.click(); await new Promise(r=>setTimeout(r,1500)); }
    pages.push(collect());
  }
  const ids = pages.flat().map(x=>x.id);
  return { perPage: pages.map(p=>p.length), unique: new Set(ids).size, missing: Array.from({length:26},(_,i)=>String(i+1)).filter(i=>!ids.includes(i)), broken: pages.flat().filter(x=>x.imgOk===false) };
}

