async () => {
  const minH = document.querySelector('.ngx-slider-pointer-min'); const maxH = document.querySelector('.ngx-slider-pointer-max');
  const key = async (el, k, n) => { el.focus(); for (let i=0;i<n;i++) { el.dispatchEvent(new KeyboardEvent('keydown', { key: k, keyCode: k==='ArrowRight'?39:37, bubbles: true })); el.dispatchEvent(new KeyboardEvent('keyup', { key: k, keyCode: k==='ArrowRight'?39:37, bubbles: true })); } await new Promise(r=>setTimeout(r,300)); };
  const before = { min: minH.getAttribute('aria-valuenow'), max: maxH.getAttribute('aria-valuenow'), floor: document.querySelector('.ngx-slider-floor')?.textContent, ceil: document.querySelector('.ngx-slider-ceil')?.textContent };
  await key(minH, 'ArrowRight', 11); await key(maxH, 'ArrowLeft', 86);
  await new Promise(r=>setTimeout(r,2000));
  const after = { min: minH.getAttribute('aria-valuenow'), max: maxH.getAttribute('aria-valuenow') };
  const items = [...document.querySelectorAll('a[href^="#/product/"]')].map(a => ({ id: a.getAttribute('href').split('/').pop(), price: parseFloat(a.querySelector('[data-test=product-price]')?.textContent.replace('$','')) }));
  return { before, after, items, pager: [...document.querySelectorAll('nav[aria-label=Pagination] li')].length };
}

