let dup = 0; const rows = [];
for (let i = 0; i < 20; i++) {
  const [a, b] = await Promise.all([post(), post()]);
  const same = a.body.invoice_number === b.body.invoice_number;
  if (same) dup++;
  rows.push(`${a.status}/${b.status} ${a.body.invoice_number} ${b.body.invoice_number}${same ? ' DUP' : ''}`);
}
console.log('product', p.id, p.name, 'stock', p.stock);
console.log('first response keys:', Object.keys((await post()).body).join(','));
console.log(rows.join('\n'));
console.log(`duplicates: ${dup}/20`);
EOF
