/** Product detail page. */
export class ProductPage {
  constructor(private readonly page: Page) {}

  async open(id: number): Promise<void> {
    await this.page.goto(`/#/product/${id}`);
    await expect(this.page.getByTestId('add-to-cart')).toBeEnabled();
  }

  /** Types the quantity (the +/− buttons do not work, BUG-008) and adds the product to the cart. */
  async addToCart(quantity = 1): Promise<void> {
    await this.page.getByTestId('quantity').fill(String(quantity));
    const linesBefore = JSON.stringify(await storedCart(this.page));
    await this.page.getByTestId('add-to-cart').click();
    await expect
      .poll(async () => JSON.stringify(await storedCart(this.page)), { message: 'cart in sessionStorage changes after Add to cart', timeout: 5_000 })
      .not.toBe(linesBefore);
  }
}

